//! High quality vector icon library using Lucide SVG paths and official brand logos.
//! Eliminates emojis and unicode text symbols across the application.

use gpui::{Pixels, Rgba, Svg, prelude::*, svg};

pub fn svg_icon(data: &'static [u8], size: Pixels, color: Rgba) -> Svg {
    svg().data(data).size(size).text_color(color)
}

