// ---------------------------------------------------------------------------
// Avatar Spec for Providers
// ---------------------------------------------------------------------------

pub struct ProviderAvatarSpec {
    pub svg_data: &'static [u8],
    pub bg: Rgba,
    pub fg: Rgba,
    pub is_multicolor: bool,
}

pub fn provider_avatar_spec(
    tool: aitoolplus_core::ToolId,
    name: &str,
    category: &str,
) -> ProviderAvatarSpec {
    let lower = name.to_lowercase();
    if category == "official" || lower.contains("official") || lower.contains("官方") {
        return match tool {
            aitoolplus_core::ToolId::ClaudeCode | aitoolplus_core::ToolId::ClaudeDesktop => {
                ProviderAvatarSpec {
                    svg_data: CLAUDE_SVG,
                    bg: crate::rgba_const(0xe07a5f22),
                    fg: crate::rgba_const(0xd97757ff),
                    is_multicolor: true,
                }
            }
            aitoolplus_core::ToolId::Codex => ProviderAvatarSpec {
                svg_data: OPENAI_SVG,
                bg: crate::rgba_const(0x10a37f22),
                fg: crate::rgba_const(0x10a37fff),
                is_multicolor: false,
            },
            aitoolplus_core::ToolId::GeminiCli => ProviderAvatarSpec {
                svg_data: GEMINI_SVG,
                bg: crate::rgba_const(0x3186ff22),
                fg: crate::rgba_const(0x3186ffff),
                is_multicolor: true,
            },
            aitoolplus_core::ToolId::Grok => ProviderAvatarSpec {
                svg_data: GROK_SVG,
                bg: crate::rgba_const(0xffffff18),
                fg: crate::rgba_const(0xf3f4f6ff),
                is_multicolor: false,
            },
            aitoolplus_core::ToolId::Kimi => ProviderAvatarSpec {
                svg_data: KIMI_SVG,
                bg: crate::rgba_const(0x027aff22),
                fg: crate::rgba_const(0x027affff),
                is_multicolor: true,
            },
            _ => ProviderAvatarSpec {
                svg_data: TERMINAL_SVG,
                bg: crate::rgba_const(0x3b82f620),
                fg: crate::rgba_const(0x3b82f6ff),
                is_multicolor: false,
            },
        };
    }

    if lower.contains("claude") || lower.contains("anthropic") {
        ProviderAvatarSpec {
            svg_data: CLAUDE_SVG,
            bg: crate::rgba_const(0xe07a5f22),
            fg: crate::rgba_const(0xd97757ff),
            is_multicolor: true,
        }
    } else if lower.contains("deepseek") {
        ProviderAvatarSpec {
            svg_data: DEEPSEEK_SVG,
            bg: crate::rgba_const(0x4d6bfe22),
            fg: crate::rgba_const(0x4d6bfeff),
            is_multicolor: true,
        }
    } else if lower.contains("openai") || lower.contains("codex") || lower.contains("chatgpt") {
        ProviderAvatarSpec {
            svg_data: OPENAI_SVG,
            bg: crate::rgba_const(0x10a37f22),
            fg: crate::rgba_const(0x10a37fff),
            is_multicolor: false,
        }
    } else if lower.contains("gemini") || lower.contains("google") {
        ProviderAvatarSpec {
            svg_data: GEMINI_SVG,
            bg: crate::rgba_const(0x3186ff22),
            fg: crate::rgba_const(0x3186ffff),
            is_multicolor: true,
        }
    } else if lower.contains("grok") || lower.contains("xai") {
        ProviderAvatarSpec {
            svg_data: GROK_SVG,
            bg: crate::rgba_const(0xffffff18),
            fg: crate::rgba_const(0xf3f4f6ff),
            is_multicolor: false,
        }
    } else if lower.contains("kimi") || lower.contains("moonshot") {
        ProviderAvatarSpec {
            svg_data: KIMI_SVG,
            bg: crate::rgba_const(0x027aff22),
            fg: crate::rgba_const(0x027affff),
            is_multicolor: true,
        }
    } else {
        ProviderAvatarSpec {
            svg_data: ZAP_SVG,
            bg: crate::rgba_const(0x3b82f620),
            fg: crate::rgba_const(0x3b82f6ff),
            is_multicolor: false,
        }
    }
}
